CREATE TABLE IF NOT EXISTS agencies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,address VARCHAR(150) NOT NULL);
CREATE TABLE IF NOT EXISTS account_users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(60) NOT NULL UNIQUE,fullName VARCHAR(120) NOT NULL,passwordHash VARCHAR(300) NOT NULL,role VARCHAR(30) NOT NULL,active BOOLEAN NOT NULL,version BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS members(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,number VARCHAR(30) NOT NULL UNIQUE,fullName VARCHAR(120) NOT NULL,phone VARCHAR(25) NOT NULL UNIQUE,email VARCHAR(150) NOT NULL,address VARCHAR(250) NOT NULL,status VARCHAR(30) NOT NULL,agency_id BIGINT NOT NULL REFERENCES agencies(id),joined DATE NOT NULL,version BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_members_agency_status ON members(agency_id,status);
CREATE TABLE IF NOT EXISTS operations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id BIGINT NOT NULL REFERENCES members(id),kind VARCHAR(30) NOT NULL,state VARCHAR(30) NOT NULL,amount NUMERIC(18,0) NOT NULL CHECK(amount>0),interest NUMERIC(5,2) NOT NULL,dueDate DATE,loan_id BIGINT REFERENCES operations(id),created TIMESTAMP NOT NULL,note VARCHAR(250),author VARCHAR(60) NOT NULL,version BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_operations_member_state ON operations(member_id,state);
CREATE INDEX IF NOT EXISTS idx_operations_date ON operations(created);
CREATE TABLE IF NOT EXISTS audit_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,created TIMESTAMP NOT NULL,actor VARCHAR(60) NOT NULL,action VARCHAR(500) NOT NULL);
CREATE TABLE IF NOT EXISTS email_outbox(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,recipient VARCHAR(150) NOT NULL,subject VARCHAR(200) NOT NULL,body VARCHAR(4000) NOT NULL,created TIMESTAMP NOT NULL,sent TIMESTAMP,state VARCHAR(30) NOT NULL,attempts INTEGER NOT NULL,error VARCHAR(200));
CREATE TABLE IF NOT EXISTS savings_accounts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id BIGINT NOT NULL UNIQUE REFERENCES members(id),number VARCHAR(40) NOT NULL UNIQUE,opened DATE NOT NULL);
